INSERT INTO careers (slug, title, category_slug, tagline, demand, education, skills, typical_work, salary_range, growth_path, icon, description, sort_order) VALUES ('plumber', 'Plumber', 'skilled-trades', 'Skilled Trade · Hands-on Work', 'Stable', 'ITI Diploma in Plumbing', ARRAY['Pipefitting','Blueprint Reading','Problem Solving','Safety Standards'], 'Installing and repairing water, gas and drainage systems', '₹2L – ₹6.5L / year', ARRAY['Apprentice','Plumber','Senior Plumber','Contractor / Business Owner'], 'wrench', 'Plumbers install and maintain the water, gas and drainage systems every building depends on — a stable, hands-on trade entered through an ITI diploma.', 1);
INSERT INTO careers (slug, title, category_slug, tagline, demand, education, skills, typical_work, salary_range, growth_path, icon, description, sort_order) VALUES ('fitness-trainer', 'Fitness Trainer', 'sports-fitness', 'Health · Coaching · Wellness', 'Emerging', 'Certification in Fitness/Sports Science (any stream)', ARRAY['Exercise Science','Nutrition Basics','Motivation & Coaching','Client Programming'], 'Designing training programs and coaching clients toward fitness goals', '₹2L – ₹10L / year', ARRAY['Trainee','Fitness Trainer','Senior Trainer','Gym/Studio Owner'], 'trophy', 'Fitness Trainers design workout and nutrition programs and coach clients toward health and performance goals, in gyms, studios or independently.', 0);
INSERT INTO careers (slug, title, category_slug, tagline, demand, education, skills, typical_work, salary_range, growth_path, icon, description, sort_order) VALUES ('entrepreneur', 'Entrepreneur', 'entrepreneurship', 'Startups · Innovation · Ownership', 'High Demand', 'Any background — the venture is the credential', ARRAY['Problem Solving','Resilience','Sales','Financial Planning'], 'Building and running your own venture, from idea to scale', 'Variable — equity & revenue-based', ARRAY['Idea & Validation','Founder','Scaling Startup','Established Business','Serial Entrepreneur'], 'rocket', 'Entrepreneurs identify problems worth solving and build ventures around them — taking on risk and ownership in exchange for the chance to build something new.', 0);
INSERT INTO careers (slug, title, category_slug, tagline, demand, education, skills, typical_work, salary_range, growth_path, icon, description, sort_order) VALUES ('ai-ml-engineer', 'AI/ML Engineer', 'emerging-careers', 'Artificial Intelligence · Deep Learning', 'High Demand', 'B.Tech/M.Tech in CS/AI or strong self-taught portfolio', ARRAY['Python','Deep Learning','MLOps','Mathematics'], 'Building and deploying machine learning and AI systems at scale', '₹8L – ₹45L / year', ARRAY['ML Engineer','Senior ML Engineer','AI Lead','Head of AI'], 'bulb', 'AI/ML Engineers build the machine learning systems behind modern products — from recommendation engines to generative AI, one of the fastest-growing fields today.', 0);
INSERT INTO careers (slug, title, category_slug, tagline, demand, education, skills, typical_work, salary_range, growth_path, icon, description, sort_order) VALUES ('sustainability-consultant', 'Sustainability Consultant', 'emerging-careers', 'ESG · Climate · Strategy', 'Emerging', 'Any degree + sustainability/ESG certification', ARRAY['ESG Frameworks','Data Analysis','Policy Knowledge','Stakeholder Communication'], 'Advising organizations on environmental, social and governance strategy', '₹6L – ₹22L / year', ARRAY['Analyst','Consultant','Senior Consultant','Practice Lead'], 'leaf', 'Sustainability Consultants help organizations reduce environmental impact and meet ESG goals — a fast-growing field as climate strategy becomes core business.', 1);
